// Recepcionista: deja el mensaje con el MISMO formato venga de donde venga
// (Telegram o la entrada de pruebas del examinador, proyecto 11).
const j = $input.first().json;
let m;
if (j.message) {
  m = {
    origen: 'telegram',
    chat_id: String(j.message.chat.id),
    nombre: j.message.from?.first_name ?? 'cliente',
    texto: j.message.text ?? '',
    prompt_prueba: '',
  };
} else {
  const b = j.body ?? {};
  m = {
  origen: 'prueba',
  // Prefijo para que la memoria de una prueba nunca se mezcle con un chat real.
  chat_id: 'prueba-' + String(b.conversacion_id ?? 'sin-id'),
  nombre: String(b.nombre ?? 'cliente de prueba'),
  texto: String(b.texto ?? ''),
  // El examinador puede mandar el prompt que quiere probar; si no, se usa el de Config.
  prompt_prueba: String(b.prompt ?? ''),
  };
}

// «Post-it» para el agente: su memoria guarda lo que dijo, pero no lo que HIZO.
// «Leer respuesta del agente» apunta qué herramientas usó con cada chat, y aquí
// se lo recordamos antes de que conteste.
const agenda = $getWorkflowStaticData('global');
const UN_DIA = 24 * 60 * 60 * 1000;  // el post-it caduca a las 24 h
const reciente = hora => Boolean(hora) && Date.now() - hora < UN_DIA;
let nota = '';
if (reciente(agenda.derivados?.[m.chat_id])) {
  nota = '[Nota del sistema: ya avisaste al equipo humano en esta conversación. NO vuelvas a usar derivar_a_persona; dile al cliente que el equipo ya está avisado.]';
} else if (!reciente(agenda.con_numero?.[m.chat_id]) && !/\b\d{4,}\b/.test(m.texto)) {
  nota = '[Nota del sistema: todavía no conoces el número de pedido de este cliente. No uses derivar_a_persona sin él, salvo que el cliente se niegue a darlo.]';
}
m.texto_agente = nota ? `${m.texto}\n\n${nota}` : m.texto;
return [{ json: m }];

