// Convierte la respuesta del agente en datos ordenados, calcula la
// seguridad con reglas fijas y prepara la línea de transparencia.
const salida = String($json.output ?? '');
const pasos = $json.intermediateSteps ?? [];
const config = $('Config').first().json;
const mensaje = $('Normalizar mensaje').first().json;

let datos;
let formatoCorrecto = true;
try {
  // Los saltos de línea dentro del texto rompen el JSON: se cambian por espacios
  // (fuera de las comillas un espacio vale lo mismo, así que no estropea nada).
  const limpio = salida.replace(/```json|```/g, '').replace(/[\r\n\t]+/g, ' ').trim();
  datos = JSON.parse(limpio.slice(limpio.indexOf('{'), limpio.lastIndexOf('}') + 1));
  if (!String(datos.respuesta ?? '').trim()) throw new Error('respuesta vacía');
} catch (error) {
  datos = { respuesta: salida.trim() || 'Perdona, no he podido procesar tu mensaje. ¿Puedes repetirlo?',
            motivo: 'la IA no devolvió el formato esperado' };
  formatoCorrecto = false;
}

// Las herramientas salen de lo que el agente HIZO de verdad, no de lo que dice.
const herramientas = [...new Set(pasos.map(p => p.action?.tool).filter(Boolean))];
const cliente = String(mensaje.texto ?? '').toLowerCase();
const respuesta = String(datos.respuesta ?? '').toLowerCase();

// Agenda de lo que el agente HIZO con cada chat (la lee «Normalizar mensaje»).
// Se guarda la hora, y lo de más de 24 h se borra para que no crezca sin fin.
const agenda = $getWorkflowStaticData('global');
const ahora = Date.now();
for (const lista of ['derivados', 'con_numero']) {
  agenda[lista] = agenda[lista] ?? {};
  for (const [chat, hora] of Object.entries(agenda[lista])) {
    if (ahora - hora > 24 * 60 * 60 * 1000) delete agenda[lista][chat];
  }
}
if (herramientas.includes('derivar_a_persona')) agenda.derivados[mensaje.chat_id] = ahora;
if (herramientas.includes('consultar_pedido')) agenda.con_numero[mensaje.chat_id] = ahora;

// SEGURIDAD: no se la preguntamos a la IA (siempre dice 100). Empieza en 100
// y cada señal de riesgo resta puntos. Así siempre se calcula igual.
const senales = [
  [!formatoCorrecto, 'formato incorrecto', 100],
  [pasos.some(p => /error|refused/i.test(String(p.observation)) && !/No existe el pedido/.test(String(p.observation))),
    'una herramienta falló', 40],
  [/\b\d{4,}\b/.test(cliente) && !herramientas.includes('consultar_pedido'),
    'hay un número de pedido y no lo consultó', 40],
  [(respuesta.match(/https?:\/\/\S+/g) ?? []).some(url =>
      !config.formulario_url || !url.startsWith(String(config.formulario_url).toLowerCase())),
    'enlace desconocido', 50],
  [/reembols|dinero|descuento|compensa|indemniza/.test(cliente + ' ' + respuesta),
    'tema de dinero', 40],
  [/correo|e-?mail|instagram|whatsapp|tel[eé]fono|llamar/.test(respuesta),
    'promete un canal de contacto', 40],
];
const restas = senales.filter(([activa]) => activa);
const seguridad = Math.max(0, 100 - restas.reduce((total, [, , puntos]) => total + puntos, 0));
const detalle = restas.map(([, nombre, puntos]) => `−${puntos} ${nombre}`).join(', ');

// Telegram interpreta el texto como HTML: escapamos < > & para que
// un mensaje con esos símbolos no rompa el envío.
const html = t => String(t ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const linea = `🔧 ${herramientas.join(', ') || 'ninguna herramienta'} · 💭 ${datos.motivo || 'sin motivo'} · 🎯 seguridad ${seguridad}/100${detalle ? ` (${detalle})` : ''}`;

return [{ json: {
  chat_id: mensaje.chat_id,
  cliente: html(mensaje.nombre),
  mensaje_cliente: html(mensaje.texto),
  respuesta: html(datos.respuesta),
  motivo: html(datos.motivo),
  seguridad,
  herramientas,
  linea: html(linea),
  // modo_demo: el cliente también ve la línea de transparencia (para enseñarlo).
  // Si está apagado, el cliente solo ve la respuesta y la línea va al equipo.
  texto_cliente: config.modo_demo
    ? `${html(datos.respuesta)}\n\n<i>— ${html(linea)}</i>`
    : html(datos.respuesta),
  // Para el examinador (proyecto 11): texto sin escapar y lo que hizo de verdad.
  prueba: {
    respuesta: String(datos.respuesta ?? ''),
    motivo: String(datos.motivo ?? ''),
    formato_correcto: formatoCorrecto,
    seguridad,
    senales: restas.map(([, nombre]) => nombre),
    herramientas,
    pasos: pasos.map(p => ({
      herramienta: p.action?.tool ?? null,
      entrada: p.action?.toolInput ?? null,
      resultado: String(p.observation ?? '').slice(0, 800),
    })),
  },
} }];
